esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 topUpAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount) + (topUpAmount)); require(depositAmount <= 1000000000000000000000000000000); require(topUpAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(topUpAmount > 0);
        require(address(this).balance >= depositAmount + topUpAmount);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        c.deposit{value: topUpAmount}(); if (__ESBMC_reverted()) return;
        c.refund(); if (__ESBMC_reverted()) return;

        bool refundSucceeded = true;
        // The rule is about the caller's recorded balance after a successful refund.
        // Since refund is called above as a top-level state-changing call, its success
        // is represented by the fact that the following attempt to withdraw any positive
        // amount must fail because the caller's balance is zero.
        bool withdrawReverted;
        c.withdraw(1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        assert(refundSucceeded && withdrawReverted);
    }

    receive() external payable {}
}

