// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 depositAmount, uint256 topUpAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        topUpAmount = bound(topUpAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(topUpAmount > 0);
        vm.assume(address(this).balance >= depositAmount + topUpAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        try c.deposit{value: topUpAmount}() {} catch { return; }
        try c.refund() {} catch { return; }
        bool refundSucceeded = true;
        bool withdrawReverted;
        try c.withdraw(1) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        assertTrue(refundSucceeded && withdrawReverted);
    }

    function testFuzz_run(uint256 depositAmount, uint256 topUpAmount) public {
        _run(depositAmount, topUpAmount);
    }

    receive() external payable {}
}
